function mergeSorted(a, b) {
  const merged = [];
  let i = 0, j = 0;
  while (i < a.length && j < b.length) {
    if (a[i] <= b[j]) merged.push(a[i++]);
    else merged.push(b[j++]);
  }
  return merged.concat(a.slice(i), b.slice(j));
}
console.log(mergeSorted([1,3,5], [2,4,6]));
